d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
sessions_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

with open(sessions_file, 'r') as f:
    lines = f.readlines()

# Count all types
counts = {}
for line in lines:
    for t in ['custom_message', 'message', 'toolResult', 'model_change']:
        if t in line:
            counts[t] = counts.get(t, 0) + 1

print(f"Message counts: {counts}")

# Look for any message that contains "Demo"
print("\nLooking for Demo in messages:")
for i, line in enumerate(lines):
    if 'Demo' in line or 'demo' in line.lower():
        print(f"Line {i}: {line[:200]}")

